# Read-your-writes: route the read to primary if a recent write occurred
import time

class Database:
    def __init__(self, primary, replica):
        self.primary = primary
        self.replica = replica
        self._last_write_ts: dict[str, float] = {}
        self.STALE_WINDOW = 5.0  # seconds

    def write(self, key: str, value):
        self.primary.set(key, value)
        self._last_write_ts[key] = time.time()

    def read(self, key: str):
        last_write = self._last_write_ts.get(key, 0)
        if time.time() - last_write < self.STALE_WINDOW:
            # Recent write — read from primary to avoid stale read
            return self.primary.get(key)
        return self.replica.get(key)  # safe to use replica

