-- Atomic bank transfer: both succeed or both roll back
BEGIN;
  UPDATE accounts
    SET balance = balance - 200
    WHERE id = 'alice' AND balance >= 200;

  -- Check that the debit actually happened (not zero rows)
  DO $$
  BEGIN
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Insufficient funds';
    END IF;
  END $$;

  UPDATE accounts
    SET balance = balance + 200
    WHERE id = 'bob';
COMMIT;

// ArangoDB: query graph and documents in a single AQL statement
// Find users connected to 'alice' who have 'engineer' in their title
const aql = require('arangojs').aql;

const cursor = await db.query(aql`
  FOR v, e IN 1..2 OUTBOUND 'users/alice' GRAPH 'social'
    FILTER CONTAINS(LOWER(v.title), 'engineer')
    RETURN {
      user: v.name,
      relationship: e.type,
      company: v.company
    }
`);

const results = await cursor.all();
console.log(results);

import happybase

# HBase: create a table with two column families
connection = happybase.Connection('hbase-host')
connection.create_table(
    'users',
    families={
        'profile': {'max_versions': 1, 'compression': 'SNAPPY'},
        'activity': {'max_versions': 5, 'bloomfilter': 'ROW'}
    }
)

table = connection.table('users')

# Write: columns are named as b'family:qualifier'
table.put(b'user123', {
    b'profile:name':    b'Alice Smith',
    b'profile:email':   b'alice@example.com',
    b'activity:login':  b'2026-06-12T09:00:00Z',
})

# Read only the profile column family — activity columns not scanned
row = table.row(b'user123', columns=[b'profile'])
print(row)
